  now() {
    let t = Date.now();
    if (t <= this.lastTime) t = this.lastTime + 1;
    this.lastTime = t;
    return new Date(t).toISOString();
  }
  save(rec) {
    const { links, ...data } = rec;
    const file = path.join(this.dir, rec.slug + '.json');
